DROP TABLE IF EXISTS `tarjetas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tarjetas` (
  `id_tarjeta` int NOT NULL AUTO_INCREMENT,
  `pan` varchar(16) NOT NULL,
  `marca` varchar(45) NOT NULL,
  `tipo` varchar(45) NOT NULL,
  `fk_cuenta` int NOT NULL,
  `anyo_vencimiento` int NOT NULL,
  `mes_vencimiento` int NOT NULL,
  PRIMARY KEY (`id_tarjeta`),
  UNIQUE KEY `pan_UNIQUE` (`pan`),
  KEY `tarjetas_cuentas_idx` (`fk_cuenta`),
  CONSTRAINT `tarjetas_cuentas` FOREIGN KEY (`fk_cuenta`) REFERENCES `cuentas` (`id_cuenta`)
) ENGINE=InnoDB AUTO_INCREMENT=326 DEFAULT CHARSET=latin1;
